def reference_for(jurisdiction):
    return LEGAL.get(jurisdiction.code.upper(),dict(title=jurisdiction.framework,source=jurisdiction.source,
        items=[(d,'Definir obligación y fuente aplicable con el responsable.','Referencia configurable') for d in ('Base y finalidad','Transferencia','Seguridad','Derechos')],incident='Identificar autoridad, condiciones, destinatarios y plazos aplicables.'))
